const seen = new Set();
const out = [];
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const cleanUrl = (u) => String(u || '').toLowerCase().split('?')[0].split('#')[0].replace(/[/]+$/, '');
for (const item of $input.all()) {
  const j = item.json || {};
  const title = j.title || j.jobTitle || j.positionName || '';
  const urlKey = cleanUrl(j.url || j.jobUrl || j.link);
  const nameKey = norm(j.companyName) + '|' + norm(title);
  if ((urlKey && seen.has('u:' + urlKey)) || seen.has('n:' + nameKey)) continue;
  if (urlKey) seen.add('u:' + urlKey);
  seen.add('n:' + nameKey);
  out.push(item);
}
return out;

