const fence = String.fromCharCode(96, 96, 96);
const doc = $json;
const hm = $('Parse Hiring Manager').item.json;
const job = $('Loop Over Jobs').item.json;
const emailText = String($('Draft Outreach Email').item.json.output || '').trim();
let mat = {};
try {
  const o = $('Draft Application Materials').item.json.output;
  mat = typeof o === 'string' ? JSON.parse(o.split(fence + 'json').join('').split(fence).join('').trim()) : (o || {});
} catch (e) {
  mat = {};
}

const content = (doc.body && doc.body.content) || [];
const lastEl = content[content.length - 1] || { endIndex: 2 };
const insertAt = Math.max(1, (lastEl.endIndex || 2) - 1);
const paraText = (el) => ((el.paragraph && el.paragraph.elements) || []).map((e) => (e.textRun && e.textRun.content) || '').join('');
const fullText = content.map(paraText).join('');
const lastText = paraText(lastEl);
const lead = lastText.trim() !== '' ? '\n' : '';

const weekLabel = 'Week of ' + $now.plus({ days: 1 }).startOf('week').toFormat('LLLL d, yyyy');
const title = job.title || job.jobTitle || job.positionName || 'Role';
const company = job.companyName || 'Company';

const parts = [];
if (!fullText.includes(weekLabel)) parts.push({ text: weekLabel, style: 'H1' });
parts.push({ text: company + ' \u2014 ' + title, style: 'H2', link: job.url || '' });
if (job.url) parts.push({ text: 'Listing: ' + job.url, style: 'BODY' });
parts.push({ text: 'Outreach contact: ' + hm.contactInfo, style: 'BODY' });
parts.push({ text: 'Hiring Manager Outreach Email', style: 'LABEL' });
parts.push({ text: emailText || '(no draft generated)', style: 'BODY' });
if (mat.coverLetterRequested && mat.coverLetter) {
  parts.push({ text: 'Cover Letter Draft', style: 'LABEL' });
  parts.push({ text: String(mat.coverLetter).trim(), style: 'BODY' });
}
const qs = Array.isArray(mat.questions) ? mat.questions.filter((q) => q && q.question && q.answer) : [];
if (qs.length) {
  parts.push({ text: 'Application Questions Draft', style: 'LABEL' });
  qs.forEach((q) => parts.push({ text: 'Q: ' + q.question + '\nA: ' + q.answer, style: 'BODY' }));
}
parts.push({ text: '', style: 'BODY' });

let text = lead;
const ranges = [];
parts.forEach((p) => {
  const start = insertAt + text.length;
  text += p.text + '\n';
  ranges.push({ start, end: insertAt + text.length, style: p.style, link: p.link });
});

const rng = (start, end) => ({ startIndex: start, endIndex: end });
const requests = [
  { insertText: { location: { index: insertAt }, text } },
  { updateParagraphStyle: { range: rng(insertAt, insertAt + text.length), paragraphStyle: { namedStyleType: 'NORMAL_TEXT' }, fields: 'namedStyleType' } },
  { updateTextStyle: { range: rng(insertAt, insertAt + text.length), textStyle: { bold: false }, fields: 'bold' } }
];
ranges.forEach((r) => {
  if (r.style === 'H1' || r.style === 'H2') {
    requests.push({ updateParagraphStyle: { range: rng(r.start, r.end), paragraphStyle: { namedStyleType: r.style === 'H1' ? 'HEADING_1' : 'HEADING_2' }, fields: 'namedStyleType' } });
    if (r.style === 'H2' && r.link) {
      requests.push({ updateTextStyle: { range: rng(r.start, r.end - 1), textStyle: { link: { url: r.link } }, fields: 'link' } });
    }
  } else if (r.style === 'LABEL') {
    requests.push({ updateTextStyle: { range: rng(r.start, r.end - 1), textStyle: { bold: true }, fields: 'bold' } });
  }
});

return { json: { documentId: doc.documentId, weekLabel, body: { requests } } };

// Get incoming scraped items from Apify fetcher
const incomingItems = $input.all();

// Get existing rows pulled from Google Sheets
const existingRows = $('Get Existing Sheet Rows').all();

// Create a Set of normalized "company|title" keys from your sheet
const existingSet = new Set(
  existingRows.map(row => {
    const company = (row.json.Company || '').trim().toLowerCase();
    const title = (row.json['Job Title'] || row.json.Title || '').trim().toLowerCase();
    return `${company}|${title}`;
  })
);

// Filter incoming items: keep only those NOT already in the sheet
const filteredItems = incomingItems.filter(item => {
  const incCompany = (item.json.company || item.json.Company || '').trim().toLowerCase();
  const incTitle = (item.json.title || item.json.Title || '').trim().toLowerCase();
  const key = `${incCompany}|${incTitle}`;

  // If the sheet already has this company + title, drop it
  return !existingSet.has(key);
});

return filteredItems;

// Collect all items that passed the 85+ score filter from the loop/router
const items = $input.all();

// Sort them in descending order (highest score first)
items.sort((a, b) => {
  const scoreA = Number(a.json.score || a.json.Score || 0);
  const scoreB = Number(b.json.score || b.json.Score || 0);
  return scoreB - scoreA; 
});

// Slice the array to keep only the top 10 highest-scoring roles
const topTen = items.slice(0, 10);

return topTen;

// Get raw jobs from Apify
const items = $input.all();

// Define words that instantly disqualify a job
const excludeWords = [
  'recruiter', 
  'recruiting', 
  'talent acquisition', 
  'human resources', 
  'hr', 
  'software engineer', 
  'software developer', 
  'account executive', 
  'sales development'
];

// Filter out any job where the title contains excluded words
const filteredJobs = items.filter(item => {
  const title = (item.json.title || item.json.Title || '').toLowerCase();

  // Check if the title includes any forbidden keywords
  const isExcluded = excludeWords.some(word => title.includes(word));

  // Keep only if it's NOT excluded
  return !isExcluded;
});

return filteredJobs;
